@@ -0,0 +1,82 @@
+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+// Reproduction for "nil pointer dereference due to HelpFlag when running in
+// parallel" (urfave/cli v3, reported with osv-scanner).
+//
+// The report runs a trivial command with no arguments from parallel tests. The
+// package-level cli.HelpFlag is shared by every command, and ensureHelp resets
+// its state (hf.value = nil, ...) on each Run, so a concurrent Run can see the
+// flag with a nil value and panic. The report's test only hits that window now
+// and then (it needs -count 100000); each parallel subtest here runs the same
+// command many times so a single `go test` run hits it almost every time.
+const parallelRunsPerCase = 50000
+
+func runParallelCli(args []string, hideHelp bool) {
+	cmd := &cli.Command{
+		Name:     "debug",
+		Usage:    "make an explosive entrance",
+		HideHelp: hideHelp,
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type parallelCase struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func runParallelCases(t *testing.T, hideHelp bool) {
+	t.Parallel()
+
+	tests := []parallelCase{
+		{
+			Name: "hello_world",
+			Exit: 0,
+		},
+		{
+			Name: "hello_sunshine",
+			Exit: 0,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			for i := 0; i < parallelRunsPerCase; i++ {
+				runParallelCli(tt.Args, hideHelp)
+			}
+		})
+	}
+}
+
+// Fails (nil pointer dereference) while the bug is present.
+func Test_runParallelHelpFlag(t *testing.T) {
+	runParallelCases(t, false)
+}
+
+// Control: the same parallel runs with HideHelp set, which keeps ensureHelp
+// from touching the shared HelpFlag, must pass.
+func Test_runParallelHelpFlagHideHelp(t *testing.T) {
+	runParallelCases(t, true)
+}
